import{_ as e,o as t,c as n,a2 as r}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"SSL 证书 FAQ","description":"","frontmatter":{"title":"SSL 证书 FAQ"},"headers":[],"relativePath":"ops-knowledge-base/ssl/ssl-certificate-faq.md","filePath":"ops-knowledge-base/ssl/ssl-certificate-faq.md","lastUpdated":1794311093000}'),l={name:"ops-knowledge-base/ssl/ssl-certificate-faq.md"};function o(i,a,s,d,p,h){return t(),n("div",null,[...a[0]||(a[0]=[r(`<p>本文解答有关 <strong>SSL 证书申请</strong> 和 <strong>域名控制权验证（Domain Control Validation，DCV）</strong> 的常见问题。</p><p>如需查看详细操作步骤，请参阅 <strong>《<a href="/ops-knowledge-base/ssl/ssl-certificate-verification-guide.html">SSL 证书验证方式指南</a>》</strong>。</p><h2 id="_1-验证邮件会发送到哪个邮箱" tabindex="-1">1. 验证邮件会发送到哪个邮箱？ <a class="header-anchor" href="#_1-验证邮件会发送到哪个邮箱" aria-label="Permalink to &quot;1. 验证邮件会发送到哪个邮箱？&quot;">​</a></h2><p>验证邮件会发送至 <strong>DCV 验证邮箱</strong>，而不是订单联系人邮箱。</p><p>证书颁发机构（CA）会将验证邮件发送至您申请证书时选择的 DCV 验证邮箱（例如 <strong><a href="mailto:admin@yourdomain.com" target="_blank" rel="noreferrer">admin@yourdomain.com</a></strong>、<strong><a href="mailto:webmaster@yourdomain.com" target="_blank" rel="noreferrer">webmaster@yourdomain.com</a></strong> 等），或发送至域名 <strong>WHOIS 注册邮箱</strong>。</p><p>请确保该邮箱可以正常接收邮件。</p><hr><h2 id="_2-支持哪些验证方式-验证过程中可以切换吗" tabindex="-1">2. 支持哪些验证方式？验证过程中可以切换吗？ <a class="header-anchor" href="#_2-支持哪些验证方式-验证过程中可以切换吗" aria-label="Permalink to &quot;2. 支持哪些验证方式？验证过程中可以切换吗？&quot;">​</a></h2><p>目前支持以下三种验证方式。您只需完成其中一种即可，在验证过程中也可以随时切换验证方式。</p><table tabindex="0"><thead><tr><th>验证方式</th><th>适用场景</th><th>说明</th></tr></thead><tbody><tr><td><strong>邮箱验证（Email Validation）</strong></td><td>域名邮箱可以正常接收邮件</td><td>支持发送至 admin@、administrator@、webmaster@、hostmaster@、postmaster@ 或 WHOIS 注册邮箱</td></tr><tr><td><strong>DNS 验证（DNS Validation）</strong></td><td>您可以管理域名 DNS</td><td>根据系统提示添加 DNS 解析记录，待解析生效后即可完成验证</td></tr><tr><td><strong>HTTP 文件验证（HTTP File Validation）</strong></td><td>您可以上传文件至网站根目录</td><td>将验证文件上传至 <code>/.well-known/pki-validation/</code> 目录。<strong>通配符（Wildcard）证书不支持此方式。</strong></td></tr></tbody></table><hr><h2 id="_3-多久可以收到验证邮件" tabindex="-1">3. 多久可以收到验证邮件？ <a class="header-anchor" href="#_3-多久可以收到验证邮件" aria-label="Permalink to &quot;3. 多久可以收到验证邮件？&quot;">​</a></h2><p>通常情况下，验证邮件会在<strong>几分钟内</strong>送达。</p><p>如果 <strong>30 分钟后仍未收到</strong>，请检查以下内容：</p><ul><li>是否查看了正确的 DCV 验证邮箱</li><li>是否进入垃圾邮件、广告邮件或隔离邮件目录</li><li>域名邮箱是否正常启用</li><li>域名 MX 邮件解析记录是否配置正确</li></ul><p>如果仍未收到验证邮件，建议切换为 <strong>DNS 验证</strong> 或 <strong>HTTP 文件验证</strong>，或提交工单联系我们协助处理。</p><hr><h2 id="_4-国家或邮政编码填写错误会影响验证吗" tabindex="-1">4. 国家或邮政编码填写错误会影响验证吗？ <a class="header-anchor" href="#_4-国家或邮政编码填写错误会影响验证吗" aria-label="Permalink to &quot;4. 国家或邮政编码填写错误会影响验证吗？&quot;">​</a></h2><p>不会。</p><p>域名控制权验证（DCV）仅用于确认您对域名拥有管理权限，不会受到国家、邮政编码等组织信息的影响。</p><p>不过，仍建议您填写准确的信息，以便后续证书管理和维护。</p><hr><h2 id="_5-文件验证一直显示未通过-应检查哪些内容" tabindex="-1">5. 文件验证一直显示未通过，应检查哪些内容？ <a class="header-anchor" href="#_5-文件验证一直显示未通过-应检查哪些内容" aria-label="Permalink to &quot;5. 文件验证一直显示未通过，应检查哪些内容？&quot;">​</a></h2><h3 id="_1-多个域名需要分别完成验证" tabindex="-1">（1）多个域名需要分别完成验证 <a class="header-anchor" href="#_1-多个域名需要分别完成验证" aria-label="Permalink to &quot;（1）多个域名需要分别完成验证&quot;">​</a></h3><p>如果证书包含多个域名（例如 <strong>example.com</strong> 和 <strong><a href="http://www.example.com/" target="_blank" rel="noreferrer">www.example.com</a></strong>），则需要分别上传对应的验证文件。</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://example.com/.well-known/pki-validation/filename.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>http://www.example.com/.well-known/pki-validation/filename.txt</span></span></code></pre></div><hr><h3 id="_2-验证文件路径或内容错误" tabindex="-1">（2）验证文件路径或内容错误 <a class="header-anchor" href="#_2-验证文件路径或内容错误" aria-label="Permalink to &quot;（2）验证文件路径或内容错误&quot;">​</a></h3><p>请确认：</p><ul><li>文件路径必须为：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/.well-known/pki-validation/</span></span></code></pre></div><ul><li>文件内容必须与系统提供的内容<strong>完全一致</strong></li><li>文件可通过 HTTP 正常访问，并返回 <strong>HTTP 200</strong> 状态码</li></ul><hr><h3 id="_3-cdn-或反向代理影响验证" tabindex="-1">（3）CDN 或反向代理影响验证 <a class="header-anchor" href="#_3-cdn-或反向代理影响验证" aria-label="Permalink to &quot;（3）CDN 或反向代理影响验证&quot;">​</a></h3><p>如果网站启用了 CDN 或反向代理，请：</p><ul><li>暂时绕过或关闭验证目录的缓存；</li><li>或确保证书颁发机构（CA）能够直接访问源站服务器。</li></ul><hr><h2 id="_6-证书长时间处于-pending-待签发-状态" tabindex="-1">6. 证书长时间处于 Pending（待签发）状态 <a class="header-anchor" href="#_6-证书长时间处于-pending-待签发-状态" aria-label="Permalink to &quot;6. 证书长时间处于 Pending（待签发）状态&quot;">​</a></h2><p>请按以下步骤检查：</p><ul><li>使用 <strong>Sectigo Order Status Checker</strong> 查询 DCV 验证状态；</li><li>切换为其他验证方式并保存，然后再切换回原验证方式并保存，以触发重新检测；</li><li>确认 DNS 解析记录已完成传播，或验证文件已可通过公网正常访问。</li></ul><p>完成 DCV 验证后，证书通常会在<strong>约 30 分钟内</strong>完成签发。</p><p>如果超过该时间仍未签发，请提交工单，并提供您的订单号，以便我们进一步协助处理。</p><hr><h2 id="_7-填写了错误的信息-或者误点了-cancel-取消-怎么办" tabindex="-1">7. 填写了错误的信息，或者误点了 Cancel（取消）怎么办？ <a class="header-anchor" href="#_7-填写了错误的信息-或者误点了-cancel-取消-怎么办" aria-label="Permalink to &quot;7. 填写了错误的信息，或者误点了 Cancel（取消）怎么办？&quot;">​</a></h2><h3 id="pending-待签发" tabindex="-1">Pending（待签发） <a class="header-anchor" href="#pending-待签发" aria-label="Permalink to &quot;Pending（待签发）&quot;">​</a></h3><p>域名通常无法直接修改。</p><p>请等待证书签发完成，或取消当前订单后重新申请。</p><h3 id="issued-已签发" tabindex="-1">Issued（已签发） <a class="header-anchor" href="#issued-已签发" aria-label="Permalink to &quot;Issued（已签发）&quot;">​</a></h3><p>您可以在后台使用 <strong>Replace（重新签发）</strong> 功能修改域名。</p><h3 id="cancelled-已取消" tabindex="-1">Cancelled（已取消） <a class="header-anchor" href="#cancelled-已取消" aria-label="Permalink to &quot;Cancelled（已取消）&quot;">​</a></h3><p>已取消的订单无法恢复，需要重新购买证书。</p><h3 id="_8-为什么我购买的-ssl-证书有效期只有-199-天-而不是购买时长" tabindex="-1">8：为什么我购买的 SSL 证书有效期只有 199 天，而不是购买时长？ <a class="header-anchor" href="#_8-为什么我购买的-ssl-证书有效期只有-199-天-而不是购买时长" aria-label="Permalink to &quot;8：为什么我购买的 SSL 证书有效期只有 199 天，而不是购买时长？&quot;">​</a></h3><p>根据证书行业规范，SSL 证书单次签发的最长有效期为 <strong>199 天</strong>。</p><p>如果您购买的证书服务期限超过 199 天，系统会先签发一张 <strong>199 天有效期</strong>的证书。</p><p>当该证书距离到期 <strong>30 天内</strong> 时，系统会自动重新签发（重签）下一张证书，以覆盖剩余的服务期限。</p><p>请注意，<strong>重签完成后，需要您重新下载并部署新的证书</strong>，原证书不会自动更新到您的服务器。</p><h3 id="_9-证书自动重签后-还需要重新部署吗" tabindex="-1">9：证书自动重签后，还需要重新部署吗？ <a class="header-anchor" href="#_9-证书自动重签后-还需要重新部署吗" aria-label="Permalink to &quot;9：证书自动重签后，还需要重新部署吗？&quot;">​</a></h3><p>需要。</p><p>证书自动重签仅表示系统生成了新的证书文件，不会自动部署到您的服务器。</p><p>重签完成后，请及时下载最新证书，并重新部署到服务器或 Web 服务中，确保网站能够继续正常使用 HTTPS，避免因证书过期而影响网站访问。</p><hr><h2 id="_10-技术支持" tabindex="-1">10. 技术支持 <a class="header-anchor" href="#_10-技术支持" aria-label="Permalink to &quot;10. 技术支持&quot;">​</a></h2><p>如需进一步协助，请通过客户中心提交工单，并提供以下信息：</p><ul><li>SSL 订单号或申请的域名</li><li>当前使用的验证方式</li><li>已尝试过的操作步骤</li><li>相关错误截图（如有）</li></ul><p>这样将有助于我们更快地协助您完成排查。</p>`,66)])])}const u=e(l,[["render",o]]);export{g as __pageData,u as default};
